import { llms, loader } from 'fumadocs-core/source';
import { docsRoute } from './shared';
import { i18n } from './i18n';
import { defineDocs } from 'fumadocs-mdx/macro';
import { metaSchema, pageSchema } from 'fumadocs-core/source/schema';

/**
 * The documentation collection.
 *
 * `content/docs/` is generated by `scripts/sync-content.mjs` from the
 * repository's own `docs/` tree, which stays the single source of truth. The
 * generated directory is gitignored: it exists only for the build, so the
 * repository never carries a second copy of its own documentation that could
 * drift from the first.
 */
const docs = defineDocs({
  dir: 'content/docs',
  docs: {
    schema: pageSchema,
    postprocess: {
      includeProcessedMarkdown: true,
    },
  },
  meta: {
    schema: metaSchema,
  },
});

export const source = loader({
  baseUrl: docsRoute,
  i18n,
  source: docs.toFumadocsSource(),
  plugins: [],
});

export const docsLlms = llms(source, {
  renderPage: async (page) => `# ${page.data.title} (${page.url})

${await page.data.getText('processed')}`,
});
